const [a, b] = line.slice("diff --git ".length).split(" ");
const oldPath = a.slice(2); // strip "a/"
const newPath = b.slice(2); // strip "b/"
const renamed = oldPath !== newPath;
current = {
    path: newPath,
    from: renamed ? oldPath : null,
    status: renamed ? "renamed" : "modified",
    binary: false,
    added: 0,
    removed: 0,
};
files.push(current);
inHunks = false;
continue;

if (line.startsWith("+")) current.added++;
else if (line.startsWith("-")) current.removed++;
continue;

if (line.startsWith("@@")) inHunks = true;
else if (line.startsWith("new file mode")) current.status = "added";
else if (line.startsWith("deleted file mode")) current.status = "deleted";
else if (line.startsWith("Binary files ")) current.binary = true;

if (line.startsWith("@@")) inHunks = true;
else if (line === "--- /dev/null") current.status = "added";
else if (line === "+++ /dev/null") current.status = "deleted";
else if (line.startsWith("Binary files ")) current.binary = true;

if (line.startsWith("+") && !line.startsWith("+++")) current.added++;
else if (line.startsWith("-") && !line.startsWith("---")) current.removed++;
continue;
